def drawdowns(prices):
    # one value per price: the fall from the running peak, 0 or negative
    out, peak = [], prices[0]
    for p in prices:
        peak = max(peak, p)
        out.append(p / peak - 1)
    return out

PATH = [250.00, 262.50, 210.00, 231.00, 273.00, 245.70, 286.65, 229.32, 240.79, 300.00, 285.00, 270.00]

@pytest.mark.parametrize("prices, expected", [
    ([100.00, 120.00, 90.00, 120.00], [0.0, 0.0, -0.25, 0.0]),
    ([80.00], [0.0]),
    ([100.00, 50.00, 75.00], [0.0, -0.5, -0.25]),   # a partial recovery
])
def test_drawdowns_by_hand(prices, expected):
    assert drawdowns(prices) == pytest.approx(expected)

def test_drawdowns_never_positive():
    assert all(d <= 0 for d in drawdowns(PATH))

def test_one_drawdown_per_price():
    assert len(drawdowns(PATH)) == len(PATH)

