def max_drawdown(prices):
    peak, worst = prices[0], 0.0
    for p in prices:
        peak = max(peak, p)
        worst = min(worst, p / peak - 1)
    return worst

def summarise(csv_text):
    closes = read_closes(csv_text)
    return {"days": len(closes), "total_return": closes[-1] / closes[0] - 1,
            "max_drawdown": max_drawdown(closes)}

@pytest.fixture
def prices_csv():
    # newest first, UK dates, across a month end
    return """Date,Close
02/04/2026,104.50
01/04/2026,99.00
31/03/2026,110.00
30/03/2026,108.00
27/03/2026,100.00
"""

@pytest.fixture
def summary(prices_csv):
    return summarise(prices_csv)

def test_days(summary):
    assert summary["days"] == 5

def test_total_return(summary):
    # oldest close 100.00 on 27 March, newest 104.50 on 2 April
    assert summary["total_return"] == pytest.approx(104.50 / 100.00 - 1)

def test_max_drawdown(summary):
    # peak 110.00 on 31 March, trough 99.00 on 1 April
    assert summary["max_drawdown"] == pytest.approx(99.00 / 110.00 - 1)

