import pytest


def ma_signal(closes, n):
    # Position for day t: 1 if close t - 1 is above the mean of closes t - n to t - 1, else 0.
    # Day t may use closes up to t - 1 only. Days before t = n are flat.
    # n below 1 must raise ValueError("n must be at least 1").
    if n < 1:
        raise ValueError("n must be at least 1")
    out = []
    for t in range(len(closes)):
        window = closes[t - n:t]
        out.append(1 if t >= n and closes[t - 1] > sum(window) / n else 0)
    return out

closes = [100.00, 104.00, 102.00, 107.00, 103.00, 108.00]

@pytest.mark.parametrize("n, expected", [
    (2, [0, 0, 1, 0, 1, 0]),   # day 2: 104 > 102; day 4: 107 > 104.5
    (3, [0, 0, 0, 0, 1, 0]),   # day 3: 102 is not above 102; day 4: 107 > 104.33
])
def test_ma_signal_by_hand(n, expected):
    assert ma_signal(closes, n) == expected

def test_last_close_moves_nothing():
    assert ma_signal(closes[:-1] + [1.00], 2) == ma_signal(closes, 2)

def test_window_below_one_raises():
    with pytest.raises(ValueError, match="at least 1"):
        ma_signal(closes, 0)

